/**
 * Build src/data/arenaMindRatings.ts: Emerald's Battle Arena "Mind" rating per
 * move, for #21.
 *
 * WHY A GENERATED FILE: the Arena judges Mind by summing a hand-set table,
 * pokeemerald src/battle_arena.c sMindRatings -- +1 for most attacks, -1 for
 * Protect, Detect and the like, 0 for anything not listed. It is not derivable
 * from any move property, so it is extracted from the pinned disassembly
 * (scripts/trainers/sources.mjs). Move constants map to national move ids
 * through include/constants/moves.h (Gen 3's ids are the national ones).
 * Only non-zero ratings are written. Throws on an unknown constant.
 *
 * Usage: node scripts/build-arena-data.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { REPOS, ensureSources } from './trainers/sources.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const dir = ensureSources(join(ROOT, '.cache/trainers')).pokeemerald

const ids = new Map(
  [
    ...readFileSync(join(dir, 'include/constants/moves.h'), 'utf8').matchAll(
      /^#define (MOVE_\w+)\s+(\d+)\s*$/gm,
    ),
  ].map((m) => [m[1], Number(m[2])]),
)
const src = readFileSync(join(dir, 'src/battle_arena.c'), 'utf8')
const start = src.indexOf('sMindRatings[')
if (start < 0) throw new Error('no sMindRatings in battle_arena.c')
const body = src.slice(start, src.indexOf('};', start))
const rows = [...body.matchAll(/\[(MOVE_\w+)\]\s*=\s*(-?\d+)/g)].map((m) => {
  const id = ids.get(m[1])
  if (id == null) throw new Error(`unknown move constant ${m[1]}`)
  return [id, Number(m[2]), m[1]]
})
if (rows.length < 200) throw new Error(`expected ~230 ratings, got ${rows.length}`)
const nonZero = rows.filter((r) => r[1] !== 0).sort((a, b) => a[0] - b[0])

const out = `/**
 * GENERATED by scripts/build-arena-data.mjs -- do not edit by hand.
 *
 * Emerald's Battle Arena Mind rating per national move id, from
 * pret/pokeemerald @ ${REPOS.pokeemerald.sha.slice(0, 7)} src/battle_arena.c sMindRatings.
 * A move not listed rates 0. Read by #21.
 */
export const ARENA_MIND_RATING: Readonly<Record<number, number>> = {
${nonZero.map(([id, r, name]) => `  ${id}: ${r}, // ${name}`).join('\n')}
}
`
writeFileSync(join(ROOT, 'src/data/arenaMindRatings.ts'), out)
console.log(
  `wrote ${nonZero.length} non-zero ratings (${nonZero.filter((r) => r[1] < 0).length} negative) of ${rows.length} listed`,
)
